  "tour.finish": "Done",
  "tour.home.status.title": "Am I safe?",
  "tour.home.status.body": "This card answers first: whether your cash stays above the minimum reserve you set, today's cash, and the points that matter. “Why” opens what is driving it. Below it, the recommended next step says what to do, what it costs and who decides.",
  "tour.nav.title": "Your five sections",
  "tour.nav.body": "Each section answers one question. “Ask FLOW”, in the corner, answers in your own words and only acts when you confirm.",
  "tour.sec.home": "the answer and the next step.",
  "tour.sec.deals": "what a buyer asks for, what it would cost you, and what to answer.",
  "tour.sec.cash": "the risk, every way to cover a gap, and the forecast.",
  "tour.sec.receivables": "who owes you, who is late, and what arrived.",
  "tour.sec.activity": "everything that happened, in order, and what was refused.",
  "tour.deals.inbox.title": "Your inbox",
  "tour.deals.inbox.body": "Each buyer's messages sit in one thread. Open a message to have FLOW read it, then check it against your limits.",
  "tour.deals.answer.title": "What to answer",
  "tour.deals.answer.body": "The recommendation comes first, then the priced response. Nothing is sent to the buyer until you confirm the send.",
  "tour.cash.risk.title": "How much risk",
  "tour.cash.risk.body": "Today's cash against your minimum cash reserve, and when cash would first become unsafe.",
  "tour.cash.options.title": "Other ways to cover the gap",
  "tour.cash.options.body": "Plans are grouped the way FLOW checked them: the recommended plan, other ways that work, then plans that depend on a buyer or fall short. A number is the ranking among plans you can run.",
  "tour.recv.summary.title": "Who owes you",
  "tour.recv.summary.body": "What is open, what is late, and the next payment to arrive.",
  "tour.recv.open.title": "Open invoices",
  "tour.recv.open.body": "Late invoices come first, then by due date. With the collections ranking on, the order follows what each collection saves you.",
  "tour.activity.list.title": "Everything that happened",
  "tour.activity.list.body": "Newest first, in plain words. “Evidence” under a row holds the exact record.",
  "tour.activity.refused.title": "What FLOW refused",
  "tour.activity.refused.body": "Requests that were refused, and messages that were set aside, with the reason.",
  "tour.approvals.title": "A question for you",
  "tour.approvals.body": "FLOW does not approve for you. Approve runs it; Decline closes it. The reason it needs you is on the card.",
  "tour.limits.title": "What FLOW may do alone",
  "tour.limits.body": "The limits you signed. Anything beyond them waits for you.",
